def get_typed_annotation(annotation: Any, globalns: Dict[str, Any]) -> Any:
    if isinstance(annotation, str):
        forward_ref = ForwardRef(annotation)
        evaluated = evaluate_forwardref(forward_ref, globalns, globalns)
        if evaluated is type(None):
            return None
        if evaluated is not forward_ref:
            return evaluated
    return annotation
